import{d as n,C as r,o,c as s,j as a,a as i,E as d,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"荀子·第25篇·成相","description":"《荀子·成相》——以韵文议论治乱、用人与历史得失。","frontmatter":{"title":"荀子·第25篇·成相","description":"《荀子·成相》——以韵文议论治乱、用人与历史得失。","category":"guide","aliases":["荀子成相","荀子第25篇"],"source":["维基文库《荀子/成相篇》，修订号 382197"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-25.md","filePath":"lizhimingde/xunzi/chapter-25.md","lastUpdated":1794362429000}'),p={name:"lizhimingde/xunzi/chapter-25.md"},b=n({...p,setup(u){const t=[{id:"p001",sentences:[["请成相，世之殃，愚暗愚暗堕贤良。人主无贤，如瞽无相何伥伥！请布基，慎圣人，愚而自专事不治。主忌苟胜，群臣莫谏必逢灾。论臣过，反其施，尊主安国尚贤义。拒谏饰非，愚而上同国必祸。曷谓罢？国多私，比周还主党与施。远贤近谗，忠臣蔽塞主埶移。曷谓贤？明君臣，上能尊主下爱民。主诚听之，天下为一海内宾。主之孽，谗人达，贤能遁逃国乃蹙。愚以重愚，暗以重暗成为桀。世之灾，妒贤能，飞廉知政任恶来。卑其志意，大其园圃高其台。武王怒师牧野，纣卒易乡启乃下。武王善之，封之于宋立其祖。世之衰，谗人归，比干见刳箕子累。武王诛之，吕尚招麾殷民怀。世之祸，恶贤士，子胥见杀百里徙。穆公任之，强配五伯六卿施。世之愚，恶大儒，逆斥不通孔子拘。展禽三绌，春申道缀基毕输。请牧基，贤者思，尧在万世如见之。谗人罔极，险陂倾侧此之疑。基必施，辨贤、罢，文、武之道同伏戏。由之者治，不由者乱何疑为？凡成相，辨法方，至治之极复后王。复慎、墨、季、惠，百家之说诚不详。治复一，修之吉，君子执之心如结。众人贰之，谗夫弃之形是诘。水至平，端不倾，心术如此象圣人。而有埶，直而用抴必参天。世无王，穷贤良，𣉱人刍豢仁人糟糠。礼乐灭息，圣人隐伏墨术行。治之经，礼与刑，君子以修百姓宁。明德慎罚，国家既治四海平。治之志，后埶富，君子诚之好以待。处之敦固，有深藏之能远思。思乃精，志之荣，好而壹之神以成。精神相反，一而不贰为圣人。治之道，美不老，君子由之佼以好。下以教诲子弟，上以事祖考。成相竭，辞不蹙，君子道之顺以达。宗其贤良，辨其殃孽。"]]},{id:"p002",sentences:[["请成相，道圣王，尧、舜尚贤身辞让。许由、善卷，重义轻利行显明。尧让贤，以为民，氾利兼爱德施均。辨治上下，贵贱有等明君臣。尧授能，舜遇时，尚贤推德天下治。虽有圣贤，适不遇世孰知之？尧不德，舜不辞，妻以二女任以事。大人哉舜！南面而立万物备。舜授禹，以天下，尚得推贤不失序。外不避仇，内不阿亲贤者予。禹劳心力，尧有德，干戈不用三苗服。举舜甽亩，任之天下身休息。得后稷，五谷殖，夔为乐正鸟兽服。契为司徒，民知孝弟尊有德。禹有功，抑下鸿，辟除民害逐共工。北决九河，通十二渚疏三江。禹傅土，平天下，躬亲为民行劳苦。得益、皋陶、横革、直成为辅。契玄王，生昭明，居于砥石迁于商。十有四世，乃有天乙是成汤。天乙汤，论举当，身让卞随举牟光。道古贤圣基必张。"]]},{id:"p003",sentences:[["愿陈辞，世乱恶善不此治。隐讳疾贤，良由奸诈鲜无灾。患难哉！阪为先，圣知不用愚者谋。前车已覆，后未知更何觉时！不觉悟，不知苦，迷惑失指易上下。中不上达，蒙揜耳目塞门户。门户塞，大迷惑，悖乱昏莫不终极。是非反易，比周欺上恶正直。正直恶，心无度，邪枉辟回失道途。己无邮人，我独自美岂独无故！不知戒，后必有，恨后遂过不肯悔。谗夫多进，反复言语生诈态。人之态，不如备，争宠嫉贤利恶忌。妒功毁贤，下敛党与上蔽匿。上壅蔽，失辅埶，任用谗夫不能制。郭公长父之难，厉王流于彘。周幽、厉，所以败，不听规谏忠是害。嗟我何人，独不遇时当乱世！欲衷对，言不从，恐为子胥身离凶。进谏不听，刭而独鹿弃之江。观往事，以自戒，治乱是非亦可识。托于成相以喻意。"]]},{id:"p004",sentences:[["请成相，言治方，君论有五约以明。君谨守之，下皆平正国乃昌。臣下职，莫游食，务本节用财无极。事业听上，莫得相使一民力。守其职，足衣食，厚薄有等明爵服。利往卬上，莫得擅与孰私得？君法明，论有常，表仪既设民知方。进退有律，莫得贵贱孰私王？君法仪，禁不为，莫不说教名不移。修之者荣，离之者辱孰它师？刑称陈，守其银，下不得用轻私门。罪祸有律，莫得轻重威不分。请牧祺，明有基，主好论议必善谋。五听修领，莫不理续主执持。听之经，明其请，参伍明谨施赏刑。显者必得，隐者复显民反诚。言有节，稽其实，信、诞以分赏罚必。下不欺上，皆以情言明若日。上通利，隐远至，观法不法见不视。耳目既显，吏敬法令莫敢恣。君教出，行有律，吏谨将之无铍、滑。下不私请，各以宜舍巧拙。臣谨修，君制变，公察善思论不乱。以治天下，后世法之成律贯。"]]},{id:"p005",sentences:[["此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。"]]},{id:"p006",sentences:[["Public domainPublic domainfalsefalse"]]}];return(c,e)=>{const l=r("DaoTextReading");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"荀子·第25篇·成相",tabindex:"-1"},[i("荀子·第25篇·成相 "),a("a",{class:"header-anchor",href:"#荀子·第25篇·成相","aria-label":'Permalink to "荀子·第25篇·成相"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇讨论：以韵文议论治乱、用人与历史得失。",-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"原文已录入；段级白话、字词点查与三问解读待逐篇补充。原文录入不等于解读完成。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=a("p",null,"经典阅读保留段落；切换「竹简」可连续通读。此阶段按来源自然段呈现，不为未整理的段落预填释义。",-1)),d(l,{sections:t,"default-mode":"classic",tone:"ink",colophon:"荀子 · 成相","aria-label":"荀子·成相原文"}),e[5]||(e[5]=h("",8))])}}});export{f as __pageData,b as default};
